function productSubtotal(){return state.cart.reduce((sum,item)=>sum+item.price*item.quantity,0)}
function orderedVialCount(){return state.cart.reduce((sum,item)=>sum+(Number(item.vials)||1)*item.quantity,0)}
function cartNeedsBacWater(){return state.cart.some(item=>!item.prepared&&!item.oilBased&&!item.tablet)}
function bacDiscountRate(){const quantity=Number(state.bacQuantity)||0;return quantity>=10?.20:quantity>=5?.15:quantity>=3?.10:0}
