function bacWaterDiscount(){return bacWaterRegularTotal()*bacDiscountRate()}
function bacWaterTotal(){return Math.round((bacWaterRegularTotal()-bacWaterDiscount())*100)/100}
function subtotal(){return productSubtotal()+bacWaterTotal()}
function fulfillmentMethod(){return $("#fulfillment-pickup")?.checked?"Pickup":"Shipping"}
function fulfillmentFee(){return state.cart.length&&fulfillmentMethod()==="Shipping"?10:0}
function orderTotal(){return state.cart.length?subtotal()+fulfillmentFee():0}
function orderSummary(){if(!state.cart.length)return"No items";const method=fulfillmentMethod(),bacQuantity=Number(state.bacQuantity)||0,lines=state.cart.map(item=>`${item.quantity} x ${item.name} — ${item.strength} — ${item.packageLabel} (${item.discount}) @ ${money.format(item.price)} = ${money.format(item.quantity*item.price)}`);if(cartNeedsBacWater()){if(bacQuantity)lines.push(`${bacQuantity} x Reconstitution/BAC Water - 0.9% benzyl alcohol — quantity discount applied — regular ${money.format(bacWaterRegularTotal())}, discount -${money.format(bacWaterDiscount())}, total ${money.format(bacWaterTotal())}`);else lines.push("Reconstitution/BAC Water - 0.9% benzyl alcohol — 0 selected")}return`${lines.join("\n")}\nProducts: ${money.format(productSubtotal())}${cartNeedsBacWater()?`\nReconstitution/BAC Water - 0.9% benzyl alcohol: ${money.format(bacWaterTotal())}`:""}\nSubtotal: ${money.format(subtotal())}\nFulfillment: ${method}\n${method==="Shipping"?"Shipping: $10":"Pickup: $0"}\nOrder total: ${money.format(orderTotal())}`}
function renderCart(){const needsBac=cartNeedsBacWater();if(!needsBac)state.bacQuantity=0;const bacQuantity=Number(state.bacQuantity)||0,productLines=state.cart.map(item=>`<div class="cart-line"><div><strong>${escapeHtml(item.name)}</strong><span>${escapeHtml(item.strength)} · ${item.packageLabel} · ${item.discount}</span></div><strong>${money.format(item.price*item.quantity)}</strong><div class="quantity"><button type="button" data-action="decrease" data-key="${escapeHtml(item.key)}" aria-label="Decrease quantity">−</button><span>${item.quantity}</span><button type="button" data-action="increase" data-key="${escapeHtml(item.key)}" aria-label="Increase quantity">+</button><button type="button" class="remove" data-action="remove" data-key="${escapeHtml(item.key)}">Remove</button></div></div>`).join(""),bacLine=needsBac?`<div class="cart-line auto-supply"><div><strong>Reconstitution/BAC Water - 0.9% benzyl alcohol</strong><span>Choose 0–10 · discounts apply at 3, 5, and 10</span></div><strong>${money.format(bacWaterTotal())}</strong><label class="automatic-quantity">Quantity <select data-bac-quantity aria-label="Reconstitution/BAC Water - 0.9% benzyl alcohol quantity">${Array.from({length:11},(_,quantity)=>`<option value="${quantity}" ${quantity===bacQuantity?"selected":""}>${quantity}</option>`).join("")}</select></label><div class="automatic-quantity">${bacQuantity?`${bacQuantity} vial${bacQuantity===1?"":"s"} · saved ${money.format(bacWaterDiscount())}`:"Not included"}</div></div>`:"";cartContainer.innerHTML=state.cart.length?productLines+bacLine:`<p class="empty">No items added.</p>`;cartTotals.hidden=!state.cart.length;const method=fulfillmentMethod();cartTotals.innerHTML=state.cart.length?`<div><span>Products</span><strong>${money.format(productSubtotal())}</strong></div>${needsBac?`<div><span>Reconstitution/BAC Water - 0.9% benzyl alcohol (${bacQuantity})</span><strong>${money.format(bacWaterTotal())}</strong></div>`:""}<div><span>${method}</span><strong>${money.format(fulfillmentFee())}</strong></div><div class="total"><span>Order total</span><strong>${money.format(orderTotal())}</strong></div>`:"";cartCount.textContent=state.cart.length?`${orderedVialCount()} product vial${orderedVialCount()===1?"":"s"}${bacQuantity?` + ${bacQuantity} BAC`:""}`:"0 items";grandTotal.textContent=money.format(orderTotal());submitOrder.disabled=!state.cart.length;downloadCartPdf.disabled=!state.cart.length;$("#order-details-field").value=orderSummary();$("#order-total-field").value=money.format(orderTotal())}
function downloadCartPdfFile(){if(!state.cart.length)return;if(!window.jspdf?.jsPDF){formStatus.textContent="The PDF tool is unavailable. Please refresh and try again.";return}const doc=new window.jspdf.jsPDF({unit:"pt",format:"letter"}),margin=42,pageWidth=doc.internal.pageSize.getWidth(),pageHeight=doc.internal.pageSize.getHeight(),contentWidth=pageWidth-margin*2;let y=44;const navy=[1,30,65],orange=[230,83,0],muted=[93,107,122],line=[216,222,232];const addPageIfNeeded=height=>{if(y+height>pageHeight-48){doc.addPage();y=44}};const writeLine=(label,value,bold=false)=>{addPageIfNeeded(22);doc.setFont("helvetica",bold?"bold":"normal");doc.setFontSize(10);doc.setTextColor(...navy);doc.text(pdfText(label),margin,y);doc.text(pdfText(value),pageWidth-margin,y,{align:"right"});y+=18};doc.setFillColor(...navy);doc.roundedRect(margin,y,contentWidth,60,10,10,"F");doc.setFillColor(...orange);doc.rect(margin,y,7,60,"F");doc.setTextColor(255,255,255);doc.setFont("helvetica","bold");doc.setFontSize(24);doc.text("Retail Cart",margin+20,y+38);y+=84;doc.setTextColor(...muted);doc.setFont("helvetica","normal");doc.setFontSize(9);doc.text(`Created ${new Date().toLocaleString()}`,margin,y);y+=24;state.cart.forEach(item=>{addPageIfNeeded(55);doc.setDrawColor(...line);doc.line(margin,y,pageWidth-margin,y);y+=16;doc.setTextColor(...navy);doc.setFont("helvetica","bold");doc.setFontSize(11);doc.text(pdfText(item.name),margin,y);doc.text(money.format(item.price*item.quantity),pageWidth-margin,y,{align:"right"});y+=15;doc.setTextColor(...muted);doc.setFont("helvetica","normal");doc.setFontSize(9);doc.text(pdfText(`${item.strength} | ${item.packageLabel} | ${item.discount} | cart qty ${item.quantity}`),margin,y);y+=18});addPageIfNeeded(78);doc.setDrawColor(...line);doc.line(margin,y,pageWidth-margin,y);y+=18;if(cartNeedsBacWater()){if(state.bacQuantity>0){doc.setTextColor(...navy);doc.setFont("helvetica","bold");doc.setFontSize(11);doc.text("Reconstitution/BAC Water - 0.9% benzyl alcohol",margin,y);doc.text(money.format(bacWaterTotal()),pageWidth-margin,y,{align:"right"});y+=15;doc.setTextColor(...muted);doc.setFont("helvetica","normal");doc.setFontSize(9);doc.text(pdfText(`${state.bacQuantity} vial${state.bacQuantity===1?"":"s"} | quantity discount | saved ${money.format(bacWaterDiscount())}`),margin,y)}else{doc.setTextColor(...muted);doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text("Reconstitution/BAC Water - 0.9% benzyl alcohol quantity: 0",margin,y)}y+=32}doc.setDrawColor(...orange);doc.line(margin,y,pageWidth-margin,y);y+=22;writeLine("Products",money.format(productSubtotal()));if(cartNeedsBacWater())writeLine(`Reconstitution/BAC Water - 0.9% benzyl alcohol (${state.bacQuantity})`,money.format(bacWaterTotal()));writeLine(fulfillmentMethod(),money.format(fulfillmentFee()));y+=4;writeLine("ORDER TOTAL",money.format(orderTotal()),true);const qrSize=78,qrTop=pageHeight-margin-qrSize;if(y>qrTop-42){doc.addPage();y=44}doc.setTextColor(...muted);doc.setFont("helvetica","normal");doc.setFontSize(8);doc.text("Order request only. Payment is not collected on this website.",pageWidth/2,qrTop-30,{align:"center"});doc.setTextColor(...navy);doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text("Supplies",margin+qrSize/2,qrTop-9,{align:"center"});doc.text("ReOrder",pageWidth-margin-qrSize/2,qrTop-9,{align:"center"});doc.addImage(CART_QR.supplies,"PNG",margin,qrTop,qrSize,qrSize);doc.addImage(CART_QR.reorder,"PNG",pageWidth-margin-qrSize,qrTop,qrSize,qrSize);doc.link(margin,qrTop,qrSize,qrSize,{url:CART_QR_URLS.supplies});doc.link(pageWidth-margin-qrSize,qrTop,qrSize,qrSize,{url:CART_QR_URLS.reorder});doc.save("Retail-Cart.pdf");formStatus.textContent="Cart PDF downloaded with Supplies and ReOrder QR codes."}

downloadProductPdf.addEventListener("click",downloadSelectedProductPdf);downloadCartPdf.addEventListener("click",downloadCartPdfFile);
protocolDoseChoice.addEventListener("change",event=>{if(event.target.name!=="protocol-user-type")return;state.protocolMode=event.target.value;const doses=availableProtocolDoses(protocolFor(state.selectedProduct?.name));state.selectedProtocolDose=state.protocolMode==="starter"?0:(doses.length>1?1:0);if(state.protocolMode==="starter")state.purchaseMode="beginner";renderProtocolDoseChoice(protocolFor(state.selectedProduct?.name));renderPrices()});
protocolDoseSelect.addEventListener("change",()=>{state.selectedProtocolDose=Number(protocolDoseSelect.value)||0;renderProtocolDoseChoice(protocolFor(state.selectedProduct?.name))});
changeProduct?.addEventListener("click",()=>{selection.hidden=true;selection.closest(".finder-card")?.classList.remove("product-selected");search.value="";suggestions.hidden=true;search.focus();search.scrollIntoView({behavior:"smooth",block:"center"})});search.addEventListener("input",renderSuggestions);search.addEventListener("keydown",event=>{if(event.key==="Enter"){event.preventDefault();const first=matchingProducts()[0];if(first)chooseProduct(first.name)}});document.addEventListener("click",event=>{const button=event.target.closest?.("[data-product]");if(!button)return;event.preventDefault();if(button.closest("#quick-list-modal")){state.quickListDismissed=true;quickListModal.hidden=true}chooseProduct(button.dataset.product,button.dataset.strength||"")});quickListClose?.addEventListener("click",closeQuickList);categorySelect.addEventListener("change",renderCatalog);strengthSelect.addEventListener("change",()=>{state.selectedStrength=strengthSelect.value;renderPrices()});prices.addEventListener("click",event=>{if(event.target.closest("[data-add]"))addToCart()});prices.addEventListener("change",event=>{if(!event.target.matches('input[name="purchase-mode"]'))return;const nextMode=event.target.value;if(nextMode==="expert"&&state.purchaseMode!=="expert"){const accepted=window.confirm("Your selection will need to be reconstituted. Vials are to be frozen before reconstitution and refrigerated after.");if(!accepted){renderPrices();return}}state.purchaseMode=nextMode;renderPrices()});$(".cart-section").addEventListener("change",event=>{const select=event.target.closest("[data-bac-quantity]");if(!select)return;state.bacQuantity=Math.max(0,Math.min(10,Number(select.value)||0));renderCart();formStatus.textContent=`Reconstitution/BAC Water - 0.9% benzyl alcohol quantity set to ${state.bacQuantity}.`;});$(".cart-section").addEventListener("click",event=>{const button=event.target.closest("[data-action]");if(!button)return;const item=state.cart.find(entry=>entry.key===button.dataset.key);if(!item)return;if(button.dataset.action==="increase")item.quantity++;if(button.dataset.action==="decrease")item.quantity--;if(button.dataset.action==="remove"||item.quantity<=0)state.cart=state.cart.filter(entry=>entry.key!==item.key);renderCart()});
orderForm.addEventListener("change",event=>{if(event.target.name==="fulfillment")renderCart()});
orderForm.addEventListener("submit",async event=>{event.preventDefault();if(!state.cart.length)return;submitOrder.disabled=true;submitOrder.textContent="Sending…";formStatus.textContent="Submitting your order request…";try{const response=await fetch(orderForm.action,{method:"POST",body:new FormData(orderForm),headers:{Accept:"application/json"}});if(!response.ok)throw new Error("Submission failed");state.cart=[];state.bacQuantity=0;orderForm.reset();renderCart();formStatus.textContent="Order request sent. We will contact you to confirm availability and payment."}catch{formStatus.textContent="The order request could not be sent. Please check your information and try again."}finally{submitOrder.textContent="Submit Order Request";submitOrder.disabled=!state.cart.length}});
async function fetchInventoryEntries(){const stamp=Date.now(),sources=[`https://raw.githubusercontent.com/ThatPepLab/InStock/main/inventory.json?updated=${stamp}`,`inventory.json?updated=${stamp}`];for(const source of sources){try{const response=await fetch(source,{cache:"no-store"});if(response.ok)return await response.json()}catch(error){console.warn("Inventory source failed",source,error)}}throw new Error("Inventory unavailable")}async function refreshInventory(){try{const entries=await fetchInventoryEntries(),next=new Map(),incoming=new Map();for(const entry of Array.isArray(entries)?entries:[]){if(!entry.product||!entry.strength)continue;const key=stockKey(entry.product,entry.strength),quantity=Math.max(0,Math.floor(Number(entry.quantity)||0));if(quantity>0)next.set(key,quantity);if(entry.moreOnWay===true)incoming.set(key,{incomingQuantity:Math.max(0,Math.floor(Number(entry.incomingQuantity)||0)),expectedArrival:String(entry.expectedArrival||"").trim()})}state.inventory=next;state.incoming=incoming;state.inventoryLoaded=true;renderCatalog();renderSuggestions();renderQuickList();if(state.selectedProduct){renderStrengths();renderPrices()}}catch(error){state.inventoryLoaded=true;renderQuickList();console.warn("Inventory check failed",error)}}
fetch(`/Wholesale/catalog-data.json?updated=${Date.now()}`,{cache:"no-store"}).then(response=>{if(!response.ok)throw new Error("Catalog unavailable");return response.json()}).then(products=>{state.products=products.filter(visibleRetailProduct);state.catalogLoaded=true;const names=[...new Set(state.products.map(product=>categoryFor(product.name)))].sort();categorySelect.insertAdjacentHTML("beforeend",names.map(name=>`<option value="${escapeHtml(name)}">${escapeHtml(name)}</option>`).join(""));renderCatalog();renderQuickList()}).catch(()=>{catalogGroups.innerHTML='<div class="prompt"><strong>Catalog unavailable.</strong><span>Please refresh the page.</span></div>'});refreshInventory();setInterval(refreshInventory,300000);renderCart();
document.addEventListener("coa-data-updated",()=>{renderCatalog();if(state.selectedProduct)renderPrices()});
